namespace Offshoot.Generated;

public static class ModuleEntry
{
    public static string Process(string record)
    {
        record = (record ?? string.Empty).PadRight(8, ' ');

        string status = "E00";
        int tierLimit = 0;
        int t1Kwh = 0;
        int t2Kwh = 0;
        decimal energy = 0m;
        decimal service = 0m;
        decimal subtotal = 0m;
        char minFlag = 'N';
        decimal levy = 0m;
        decimal total = 0m;

        char custClass = record[0];
        string monthStr = record.Substring(1, 2);
        string kwhStr = record.Substring(3, 5);

        if (custClass != 'R' && custClass != 'C')
        {
            status = "E05";
        }
        else if (!IsNumeric(monthStr) || !int.TryParse(monthStr, out int monthVal) || monthVal < 1 || monthVal > 12)
        {
            status = "E06";
        }
        else if (!IsNumeric(kwhStr) || !int.TryParse(kwhStr, out int kwhVal))
        {
            status = "E09";
        }

        if (status == "E00")
        {
            int month = int.Parse(monthStr);
            int kwh = int.Parse(kwhStr);

            decimal tier1Rate;
            decimal tier2Rate;
            int baseLimit;
            int summerLimit;
            decimal minimum;

            if (custClass == 'R')
            {
                tier1Rate = 0.0912m;
                tier2Rate = 0.1185m;
                baseLimit = 600;
                summerLimit = 750;
                service = 4.25m;
                minimum = 8.50m;
            }
            else
            {
                tier1Rate = 0.1040m;
                tier2Rate = 0.0875m;
                baseLimit = 2000;
                summerLimit = 2500;
                service = 11.75m;
                minimum = 25.00m;
            }

            tierLimit = (month >= 6 && month <= 9) ? summerLimit : baseLimit;

            if (kwh > tierLimit)
            {
                t1Kwh = tierLimit;
                t2Kwh = kwh - tierLimit;
            }
            else
            {
                t1Kwh = kwh;
                t2Kwh = 0;
            }

            decimal tier1Amount = t1Kwh * tier1Rate;
            decimal tier2Amount = t2Kwh * tier2Rate;
            energy = Math.Round(tier1Amount + tier2Amount, 2, MidpointRounding.AwayFromZero);

            subtotal = energy + service;
            if (subtotal < minimum)
            {
                subtotal = minimum;
                minFlag = 'Y';
            }

            levy = Math.Round(subtotal * 0.0250m, 2, MidpointRounding.AwayFromZero);
            total = subtotal + levy;
        }

        return FormatOutput(status, tierLimit, t1Kwh, t2Kwh, energy, service, subtotal, minFlag, levy, total);
    }

    private static bool IsNumeric(string str)
    {
        if (string.IsNullOrEmpty(str))
        {
            return false;
        }

        foreach (char c in str)
        {
            if (c < '0' || c > '9')
            {
                return false;
            }
        }

        return true;
    }

    private static string FormatOutput(
        string status,
        int tierLimit,
        int t1Kwh,
        int t2Kwh,
        decimal energy,
        decimal service,
        decimal subtotal,
        char minFlag,
        decimal levy,
        decimal total)
    {
        return string.Concat(
            status,
            tierLimit.ToString("D5"),
            t1Kwh.ToString("D5"),
            t2Kwh.ToString("D5"),
            FormatAmount(energy, 7, 2),
            FormatAmount(service, 3, 2),
            FormatAmount(subtotal, 7, 2),
            minFlag,
            FormatAmount(levy, 5, 2),
            FormatAmount(total, 7, 2)
        );
    }

    private static string FormatAmount(decimal value, int intDigits, int decDigits)
    {
        long factor = 1;
        for (int i = 0; i < decDigits; i++)
        {
            factor *= 10;
        }
        long totalCents = (long)Math.Round(value * factor, MidpointRounding.AwayFromZero);
        int totalDigits = intDigits + decDigits;
        return totalCents.ToString().PadLeft(totalDigits, '0');
    }
}

using Xunit;

namespace Offshoot.Generated.Tests;

public class RateCalcModuleTests
{
    [Fact]
    public void TestInvalidCustomerClass_ReturnsE05()
    {
        string input = "X0100100";
        string output = ModuleEntry.Process(input);
        Assert.StartsWith("E05", output);
        Assert.Equal(58, output.Length);
    }

    [Fact]
    public void TestInvalidMonthNonNumeric_ReturnsE06()
    {
        string input = "RAB00100";
        string output = ModuleEntry.Process(input);
        Assert.StartsWith("E06", output);
    }

    [Fact]
    public void TestInvalidMonthOutOfRange_ReturnsE06()
    {
        string input = "R1300100";
        string output = ModuleEntry.Process(input);
        Assert.StartsWith("E06", output);

        string inputZero = "R0000100";
        string outputZero = ModuleEntry.Process(inputZero);
        Assert.StartsWith("E06", outputZero);
    }

    [Fact]
    public void TestInvalidUsageNonNumeric_ReturnsE09()
    {
        string input = "R05ABCDE";
        string output = ModuleEntry.Process(input);
        Assert.StartsWith("E09", output);
    }

    [Fact]
    public void TestResidentialStandardMonthExceedingTierLimit()
    {
        // R, Month 05, 800 kWh
        // Base limit: 600, T1=600, T2=200
        // T1 energy = 600 * 0.0912 = 54.72
        // T2 energy = 200 * 0.1185 = 23.70
        // Energy = 78.42, Service = 4.25, Subtotal = 82.67
        // Levy = 82.67 * 0.025 = 2.0667 -> 2.07
        // Total = 84.74
        string input = "R0500800";
        string output = ModuleEntry.Process(input);

        Assert.Equal(58, output.Length);
        Assert.Equal("E00", output.Substring(0, 3));
        Assert.Equal("00600", output.Substring(3, 5)); // Tier limit
        Assert.Equal("00600", output.Substring(8, 5)); // T1 kWh
        Assert.Equal("00200", output.Substring(13, 5)); // T2 kWh
        Assert.Equal("000007842", output.Substring(18, 9)); // Energy 78.42
        Assert.Equal("00425", output.Substring(27, 5)); // Service 4.25
        Assert.Equal("000008267", output.Substring(32, 9)); // Subtotal 82.67
        Assert.Equal("N", output.Substring(41, 1)); // Min flag
        Assert.Equal("0000207", output.Substring(42, 7)); // Levy 2.07
        Assert.Equal("000008474", output.Substring(49, 9)); // Total 84.74
    }

    [Fact]
    public void TestResidentialSummerMonthExceedingTierLimit()
    {
        // R, Month 07, 800 kWh
        // Summer limit: 750, T1=750, T2=50
        // T1 energy = 750 * 0.0912 = 68.40
        // T2 energy = 50 * 0.1185 = 5.925
        // Energy = 74.325 -> 74.33, Service = 4.25, Subtotal = 78.58
        // Levy = 78.58 * 0.025 = 1.9645 -> 1.96
        // Total = 80.54
        string input = "R0700800";
        string output = ModuleEntry.Process(input);

        Assert.Equal("E00", output.Substring(0, 3));
        Assert.Equal("00750", output.Substring(3, 5));
        Assert.Equal("00750", output.Substring(8, 5));
        Assert.Equal("00050", output.Substring(13, 5));
        Assert.Equal("000007433", output.Substring(18, 9));
        Assert.Equal("00425", output.Substring(27, 5));
        Assert.Equal("000007858", output.Substring(32, 9));
        Assert.Equal("N", output.Substring(41, 1));
        Assert.Equal("0000196", output.Substring(42, 7));
        Assert.Equal("000008054", output.Substring(49, 9));
    }

    [Fact]
    public void TestMinimumBillTriggered()
    {
        // R, Month 01, 10 kWh
        // T1 = 10 * 0.0912 = 0.912 -> 0.91
        // Subtotal = 0.91 + 4.25 = 5.16 < Min (8.50)
        // Subtotal raised to 8.50, MinFlag = 'Y'
        // Levy = 8.50 * 0.025 = 0.2125 -> 0.21
        // Total = 8.71
        string input = "R0100010";
        string output = ModuleEntry.Process(input);

        Assert.Equal("E00", output.Substring(0, 3));
        Assert.Equal("000000091", output.Substring(18, 9)); // Energy 0.91
        Assert.Equal("000000850", output.Substring(32, 9)); // Subtotal 8.50
        Assert.Equal("Y", output.Substring(41, 1)); // Min flag Y
        Assert.Equal("0000021", output.Substring(42, 7)); // Levy 0.21
        Assert.Equal("000000871", output.Substring(49, 9)); // Total 8.71
    }

    [Fact]
    public void TestCommercialTariff()
    {
        // C, Month 06 (Summer), 3000 kWh
        // Summer limit: 2500, T1=2500, T2=500
        // T1 energy = 2500 * 0.1040 = 260.00
        // T2 energy = 500 * 0.0875 = 43.75
        // Energy = 303.75, Service = 11.75, Subtotal = 315.50
        // Levy = 315.50 * 0.025 = 7.8875 -> 7.89
        // Total = 323.39
        string input = "C0603000";
        string output = ModuleEntry.Process(input);

        Assert.Equal("E00", output.Substring(0, 3));
        Assert.Equal("02500", output.Substring(3, 5));
        Assert.Equal("02500", output.Substring(8, 5));
        Assert.Equal("00500", output.Substring(13, 5));
        Assert.Equal("000030375", output.Substring(18, 9));
        Assert.Equal("01175", output.Substring(27, 5));
        Assert.Equal("000031550", output.Substring(32, 9));
        Assert.Equal("N", output.Substring(41, 1));
        Assert.Equal("0000789", output.Substring(42, 7));
        Assert.Equal("000032339", output.Substring(49, 9));
    }
}
